starter.css:
.banner { display: flex; justify-content: space-between; align-items: center; background: #fff4d6; padding: 4px 12px; border-radius: 8px; }
.banner p { margin: 0; }
.bar { display: flex; justify-content: space-between; align-items: center; margin-block: 12px; }
.cards { display: grid; gap: 8px; }
.card { border: 1px solid #c9c4dc; border-radius: 12px; padding: 8px 12px; }
.card h3 { margin: 0 0 6px; font-size: 1rem; }
button { font: inherit; min-block-size: 32px; min-inline-size: 32px; border-radius: 8px; border: 1px solid #5b3cc4; background: #fff; color: #5b3cc4; }
footer { margin-block-start: 12px; display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.visually-hidden { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }

